// issue-002：低库存列表按数量升序，数量相同按仓库名升序。
// 三个仓库都未配置，回退默认阈值，数量 1/1/3 均低于阈值。
func TestLowStockWarehousesOrderedByQuantityThenName(t *testing.T) {
	got := LowStockWarehouses(map[string]int{"chengdu": 3, "wuhan": 1, "xian": 1})
	want := []string{"wuhan", "xian", "chengdu"}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("LowStockWarehouses = %v, 期望 %v", got, want)
	}
}

